const staticData = $getWorkflowStaticData('global');

if (!staticData.events) staticData.events = [];
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.dailyStats) staticData.dailyStats = {};

const items = $input.all();
const event = (items[0].json.body) || items[0].json;
const today = new Date().toISOString().split('T')[0];

staticData.events.push({
  timestamp: event.timestamp || new Date().toISOString(),
  sessionId: event.sessionId || 'unknown',
  signal: event.signal || 'cold',
  userMessage: event.userMessage || '',
  botReply: event.botReply || '',
  page: event.page || '/'
});
if (staticData.events.length > 5000) {
  staticData.events = staticData.events.slice(-5000);
}

const sid = event.sessionId || 'unknown';
if (!staticData.sessions[sid]) {
  staticData.sessions[sid] = { started: new Date().toISOString(), messageCount: 0, signals: [] };
}
staticData.sessions[sid].messageCount++;
staticData.sessions[sid].lastActivity = new Date().toISOString();
if (event.signal) staticData.sessions[sid].signals.push(event.signal);

if (!staticData.dailyStats[today]) {
  staticData.dailyStats[today] = { conversations: 0, messages: 0, hotSignals: 0, warmSignals: 0, coldSignals: 0, whatsappClicks: 0, carteClicks: 0, calculateurClicks: 0, inputTokens: 0, outputTokens: 0 };
}
var day = staticData.dailyStats[today];
day.messages++;
if (staticData.sessions[sid].messageCount === 1) day.conversations++;
if (event.signal === 'hot') day.hotSignals++;
else if (event.signal === 'warm') day.warmSignals++;
else day.coldSignals++;
if (event.userMessage === 'commander_whatsapp') day.whatsappClicks++;
if (event.userMessage === 'voir_carte') day.carteClicks++;
if (event.userMessage === 'voir_calculateur') day.calculateurClicks++;
day.inputTokens += event.inputTokens || 0;
day.outputTokens += event.outputTokens || 0;

return [{ json: { status: 'stored', today: day } }];

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const query = items[0].json.query || {};
const range = query.range || '7d';

var daysBack = 7;
if (range === '30d') daysBack = 30;
if (range === '90d') daysBack = 90;
if (range === 'today') daysBack = 0;

var startDate = new Date();
startDate.setDate(startDate.getDate() - daysBack);
var startStr = startDate.toISOString().split('T')[0];

var dailyStats = staticData.dailyStats || {};
var filteredDays = Object.entries(dailyStats).filter(function(e) { return e[0] >= startStr; }).sort(function(a, b) { return a[0].localeCompare(b[0]); });

var totals = { conversations: 0, messages: 0, hotSignals: 0, warmSignals: 0, coldSignals: 0, whatsappClicks: 0, carteClicks: 0, calculateurClicks: 0, inputTokens: 0, outputTokens: 0 };

filteredDays.forEach(function(entry) {
  var day = entry[1];
  Object.keys(totals).forEach(function(key) { totals[key] += day[key] || 0; });
});

var activeSessions = Object.keys(staticData.sessions || {}).length;
var recentEvents = (staticData.events || []).slice(-50).reverse();
var conversionRate = totals.conversations > 0 ? Math.round((totals.hotSignals / totals.conversations) * 100) : 0;
var avgMessages = totals.conversations > 0 ? Math.round((totals.messages / totals.conversations) * 10) / 10 : 0;

var response = {
  range: range,
  totals: totals,
  activeSessions: activeSessions,
  conversionRate: conversionRate,
  avgMessages: avgMessages,
  dailyBreakdown: filteredDays.map(function(e) { return Object.assign({ date: e[0] }, e[1]); }),
  recentEvents: recentEvents.slice(0, 20),
  tokenCost: {
    input: totals.inputTokens,
    output: totals.outputTokens,
    estimatedCostUSD: Math.round((totals.inputTokens * 0.003 + totals.outputTokens * 0.015) / 1000 * 100) / 100
  }
};

return [{ json: response }];
